"""Author the world volume specification. Writes book artifacts only."""
from pathlib import Path
import json,re,textwrap,hashlib
W=Path(__file__).resolve().parents[1]; B=W.parent; S=B/'baseline/source'; I=json.loads((W/'script-index.json').read_text())
P=[]
def target(label,new_text=None,behavior=None):
 b=I[label];r={'source':b['path'],'label':label,'line':b['line'],'baseline_sha256':hashlib.sha256((S/b['path']).read_bytes()).hexdigest(),'current':b['text'] or '\n'.join(b['code'])}
 if new_text is not None:r['replacement_text']=new_text
 if behavior is not None:r['final_behavior']=behavior
 return r
def add(id,title,assessment,targets,dependencies=(),acceptance=(),disposition='REPAIR'):
 P.append({'id':id,'title':title,'disposition':disposition,'assessment':assessment,'targets':targets,'dependencies':list(dependencies),'acceptance':list(acceptance)})
